public static class RepairStreetRegistry {public static object Main(){if(EditorApplication.isPlayingOrWillChangePlaymode||EditorApplication.isCompiling)throw new Exception("Idle required");for(int i=0;i<SceneManager.sceneCount;i++)if(SceneManager.GetSceneAt(i).isDirty)throw new Exception("Dirty scene");EditorSceneManager.OpenScene("Assets/ShooterSurvival/Scenes/Tools/Jamsil.unity");var d=UnityEngine.Object.FindFirstObjectByType<Chapter45Director>();var archive=d.transform.Find("Preserved pre-detail street actors and hazards");if(archive==null||archive.gameObject.activeSelf)throw new Exception("Expected inactive archive");archive.name="Preserved_PreDetailed_Street_20261003";foreach(var h in d.hazards){if(h.body!=null)h.body.gameObject.SetActive(false);if(h.footprint!=null)h.footprint.SetActive(false);}EditorSceneManager.MarkSceneDirty(d.gameObject.scene);EditorSceneManager.SaveScene(d.gameObject.scene);int archived=archive.GetComponentsInChildren<Chapter45Hazard>(true).Length;
EditorSceneManager.OpenScene("Assets/ShooterSurvival/Scenes/Tools/ShoeTower.unity");d=UnityEngine.Object.FindFirstObjectByType<Chapter45Director>();int number=24,count=0;foreach(var e in d.encounters.Where(e=>e.floor==8)){var role=e.actors.Select(a=>a.GetComponent<Chapter45RoleAction>()).FirstOrDefault(a=>a!=null&&a.role==Chapter45RoleAction.Role.CalledQueue);if(role==null)continue;role.callNumber=number;number+=10;count++;}foreach(var h in d.hazards){if(h.body!=null)h.body.gameObject.SetActive(false);if(h.footprint!=null)h.footprint.SetActive(false);}EditorSceneManager.MarkSceneDirty(d.gameObject.scene);EditorSceneManager.SaveScene(d.gameObject.scene);return new{archivedHazards=archived,archive="Preserved_PreDetailed_Street_20261003",calledQueues=count,hazardLobbyHidden=true};}}
